from dataclasses import dataclass
from collections import Counter, defaultdict
import functools

@dataclass
class InventoryItem:
    name: str
    category: str
    price: float

class InventoryTracker:
    def __init__(self):
        self.items = []

    def add_item(self, name, category, price):
        self.items.append(InventoryItem(name, category, price))

    def total_value(self):
        return functools.reduce(lambda acc, item: acc + item.price, self.items, 0)

    def group_by_category(self):
        groups = defaultdict(list)
        for item in self.items:
            groups[item.category].append(item.name)
        return dict(groups)

    def most_common_category(self):
        counts = Counter(item.category for item in self.items)
        return counts.most_common(1)[0][0] if counts else None

    def price_summary(self):
        if not self.items:
            return {'min': None, 'max': None, 'avg': None}
        prices = [item.price for item in self.items]
        return {'min': min(prices), 'max': max(prices), 'avg': sum(prices) / len(prices)}
